80 |     /// There can be only one Join per Asset. Until a Join is added, no tokens of that Asset can be posted or withdrawn.
81 |     function addJoin(bytes6 assetId, IJoin join)
82 |         external
83 |         auth
84 |     {
85 |         address asset = cauldron.assets(assetId);
86 |         require (asset != address(0), "Asset not found");
87 |         require (join.asset() == asset, "Mismatched asset and join");
88 |         joins[assetId] = join;
89 |         emit JoinAdded(assetId, address(join));
90 |     }
