40 |     function getVault(bytes12 vaultId_)
41 |         internal view
42 |         returns (bytes12 vaultId, DataTypes.Vault memory vault)
43 |     {
44 |         if (vaultId_ == bytes12(0)) { // We use the cache
45 |             require (cachedVaultId != bytes12(0), "Vault not cached");
46 |             vaultId = cachedVaultId;
47 |         } else {
48 |             vaultId = vaultId_;
49 |         }
50 |         vault = cauldron.vaults(vaultId);
51 |         require (vault.owner == msg.sender, "Only vault owner");
52 |     } 
